-1 focus:outline-primary"><span class="text-xl pr-0.5">thumb_up</span><div class="font-mitr font-light text-sm">0</div></button><div class="pl-1"><button class="cursor-pointer text-2xl flex items-center justify-center min-w-10 h-10 rounded-full text-on-surface-variant font-icons notranslate hover:bg-surface-container-high focus:outline focus:outline-2 focus:outline-offset-1 focus:outline-primary"><span class="text-xl pr-0.5">thumb_down</span><div class="font-mitr font-light text-sm">0</div></button></div><div class="-mr-1"><button class="cursor-pointer text-2xl flex items-center justify-center min-w-10 h-10 rounded-full text-on-surface-variant font-icons notranslate hover:bg-surface-container-high focus:outline focus:outline-2 focus:outline-offset-1 focus:outline-primary"><span class="text-xl">bookmark_border</span></button></div></div></div><div class="w-full"><div class="md:ml-1 pl-2 md:pl-2.5 border-l border-ntr flex flex-col gap-2"><div class="whitespace-pre-wrap"><span class="italic font-light ">Ответ: </span><span><span class="hl">Камелот</span>.</span></div><div class="whitespace-pre-wrap pb-2"><span class="italic font-light ">Комментарий: </span><span>Выпущены монеты "от имени" <span class="hl">Камелота</span>, посвященные Артуриане.</span></div><div class="whitespace-pre-wrap text-sm font-light "><span class="italic font-light ">Замечания: </span>Разве Камелот не замок, а страна? (Борис Моздухов)</div><div class="whitespace-pre-wrap break-word"><span class="italic font-light ">Источники: </span><span class="">Unusial WorldCoins. 5-th edition. USA, 2008.</span></div><div><span class="italic font-light ">Автор: </span><a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1 " href="/person/1353">Алексей Паевский</a></div></div></div></div></div>
                   """;

        // Act
