        Assert.Equal("Камелот.", question.Answer);
        Assert.Equal("Выпущены монеты \"от имени\" Камелота, посвященные Артуриане.", question.Comment);
        Assert.Equal("Разве Камелот не замок, а страна? (Борис Моздухов)", question.Note);
        Assert.Contains("Алексей Паевский", question.Authors);
    }

    [Fact]
    public void ParseQuestionWithAnAcceptableAnswer()
    {
        var node = """
                   <div class="bg-surface-container-low rounded-2xl p-4 w-full flex justify-start"><div class="break-words block w-full qScroll" id="376519"><div class="flex items-end justify-between pt-1 pb-2"><div><a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1  whitespace-nowrap" href="/question/376519">Вопрос 9</a></div><div class="flex justify-end text-sm"><div class="text-right"><div class="flex flex-col"><div><a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1 " href="/pack/5402">Лига плюща-4: Принстон</a><small class="capitalize"> · апрель 2023</small></div><div class="flex justify-end flex-wrap"><a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1 " href="/tour/23173">Тур 1</a><div><span class="px-1">·</span><a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1  whitespace-nowrap" href="/person/267">Максим Мерзляков</a></div></div></div></div></div></div><div class="whitespace-pre-wrap"><span>Персонажи романа «Кольцо из <span class="hl">Камело́та</span>», действие которого происходит в двадцатом веке, под покровом ночи строят в канаве стену. Когда один из них начинает сомневаться в успехе мероприятия, второй упоминает… Какую деревню?</span></div><div class="flex flex-wrap justify-between items-center pt-1"><div class="-ml-4 unselectable"><button class="h-10 px-4 rounded-full whitespace-nowrap text-primary hover:bg-surface-container focus:outline focus:outline-2 focus:outline-offset-1 focus:outline-primary italic font-light w-min"><div class="flex flex-row justify-between items-center"><div class="flex items-center"><span class="text-on-surface-variant">Скрыть ответ</span></div><span class="font-icons notranslate text-xl pl-2 not-italic">expand_less</span></div></button></div><div class="flex unselectable flex-row items-center"><button class="cursor-pointer text-2xl flex items-center justify-center min-w-10 h-10 rounded-full text-on-surface-variant font-icons notranslate hover:bg-surface-container-high focus:outline focus:outline-2 focus:outline-offset-1 focus:outline-primary"><span class="text-xl pr-0.5">thumb_up</span><div class="font-mitr font-light text-sm">1</div></button><div class="pl-1"><button class="cursor-pointer text-2xl flex items-center justify-center min-w-10 h-10 rounded-full text-on-surface-variant font-icons notranslate hover:bg-surface-container-high focus:outline focus:outline-2 focus:outline-offset-1 focus:outline-primary"><span class="text-xl pr-0.5">thumb_down</span><div class="font-mitr font-light text-sm">0</div></button></div><div class="-mr-1"><button class="cursor-pointer text-2xl flex items-center justify-center min-w-10 h-10 rounded-full text-on-surface-variant font-icons notranslate hover:bg-surface-container-high focus:outline focus:outline-2 focus:outline-offset-1 focus:outline-primary"><span class="text-xl">bookmark_border</span></button></div></div></div><div class="w-full"><div class="md:ml-1 pl-2 md:pl-2.5 border-l border-ntr flex flex-col gap-2"><div class="whitespace-pre-wrap"><span class="italic font-light ">Ответ: </span>Пилтда́ун.</div><div class="whitespace-pre-wrap"><span class="italic font-light ">Зачёт: </span>Пильтдаун.</div><div class="whitespace-pre-wrap pb-2"><span class="italic font-light ">Комментарий: </span><span>эти герои — мошенники, которые хотят выдать построенное сооружение за развалины <span class="hl">Камелота</span> легендарного короля Арту́ра. Когда один из них сомневается в том, что подделку не распознают археологи, второй упоминает деревню Пилтдаун, намекая на Пилтдаунского человека — фальсификацию, в которую на некоторое время поверили палеоантропологи.</span></div><div class="whitespace-pre-wrap break-word"><span class="italic font-light ">Источники: </span><span class="">1. Э. Питерс. Кольцо из Камелота; <a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1  break-all" target="_blank" rel="noreferrer noopener" href="https://tinyurl.com/4325x2pk">https://tinyurl.com/4325x2pk</a>
                   2. <a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1  break-all" target="_blank" rel="noreferrer noopener" href="https://en.wikipedia.org/wiki/Piltdown">https://en.wikipedia.org/wiki/Piltdown</a>
                   3. <a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1  break-all" target="_blank" rel="noreferrer noopener" href="https://en.wikipedia.org/wiki/Piltdown_Man">https://en.wikipedia.org/wiki/Piltdown_Man</a></span></div><div><span class="italic font-light ">Автор: </span><a class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1 " href="/person/267">Максим Мерзляков</a></div><div><small><button class="cursor-pointer text-primary  hover:underline decoration-1 underline-offset-1 ">3</button> / 24 · 12.50%</small><div class="bg-surface-container-highest h-[3px] w-[200px] mt-0.5 rounded"><div class="bg-primary h-[3px] rounded" style="width: 24px;"></div></div></div></div></div></div></div>
                   """;

        // Act
        var question = Parse(node);
        
        // Assert
        Assert.Equal("Лига плюща-4: Принстон", question.PackTitle);
        Assert.Equal(new DateOnly(2023, 4, 1), question.Date);
        Assert.Equal(9, question.Number);
        Assert.Equal("Персонажи романа «Кольцо из Камело\u0301та», действие которого происходит в двадцатом веке, под покровом ночи строят в канаве стену. Когда один из них начинает сомневаться в успехе мероприятия, второй упоминает… Какую деревню?", question.Text);
        
        Assert.Equal("Пилтда\u0301ун.", question.Answer);
        Assert.Equal("Пильтдаун.", question.AcceptedAnswer);
        Assert.Equal("эти герои — мошенники, которые хотят выдать построенное сооружение за развалины Камелота легендарного короля Арту\u0301ра. Когда один из них сомневается в том, что подделку не распознают археологи, второй упоминает деревню Пилтдаун, намекая на Пилтдаунского человека — фальсификацию, в которую на некоторое время поверили палеоантропологи.", question.Comment);
        Assert.Contains("Максим Мерзляков", question.Authors);
    }
    
