    private Question Parse(string text)
    {
        var htmlDocument = new HtmlDocument();
        htmlDocument.LoadHtml(text);
        
        var htmlNode = htmlDocument.DocumentNode.FirstChild;
        
        return new QuestionHtmlParser().Parse(htmlNode.FirstChild);
    }
